pub type Weather = enum {
  Sunny(temp: Int),
  Rainy(mm: Float64),
  Cloudy,
}

fn activity(w: &Weather) -> Str {
  match w {
    Sunny(_) => { return "Beach"; }
    Rainy(_) => { return "Movie"; }
    Cloudy => { return "Park"; }
  }
}

fn temperature(w: &Weather) -> Int {
  match w {
    Sunny(temp) => { return temp; }
    Rainy(_) => { return 15; }
    Cloudy => { return 20; }
  }
}

fn main() -> Int {
  let w1 = Weather.Sunny(30);
  let w2 = Weather.Rainy(5.2);
  let w3 = Weather.Cloudy;
  return temperature(&w1) + temperature(&w2) + temperature(&w3);
}
